"""Вежливость и прощание: «спасибо», «до свидания», «спасибо, а что...».

Отдельный модуль по той же причине, что остальная логика колонки: разбор
фразы проверяется без колонки, без сети и без модели.

Зачем это. На «спокойной ночи» модель отвечала «Night to you! У меня сейчас
спокойный и полон смычка» - с английским словом посреди русской фразы и
полусловом в конце. На «не за что» - «Привет!». Это самые частые короткие
фразы в разговоре, и на них колонка выглядела хуже всего.

Вторая и более полезная половина модуля - вежливая приставка. «Спасибо, а
что сейчас погода» это один вопрос с вежливостью в начале, а не отказ
отвечать. Раньше такая фраза уходила в модель целиком, и модель отвечала,
что не знает погоды. Здесь вежливость снимается, и дальше идёт обычный
вопрос, который колонка уже умеет.

Проверки: python3 vendor/irene-va/jane_bye.py
"""

import re

# Благодарность.
_THANKS = re.compile(
    r"\b(?:спасибо|благодарю|спс|пасиб|мерси|thank\s*you|thanks)\b", re.I)
_BYE = re.compile(
    r"\b(?:до\s+свидания|до\s+встречи|пока|прощай|увидимся|до\s+завтра|"
    r"до\s+выходных|спокойной\s+ночи|доброй\s+ночи|доброе\s+утро|"
    r"добрый\s+день|спокойной)\b", re.I)
_SORRY = re.compile(
    r"\b(?:извини|извините|прости|простите|извини\s+пожалуйста|"
    r"виноват|виновата)\b", re.I)
_WELCOME = re.compile(
    r"\b(?:привет|здравствуй|здравствуйте|доброе\s+утро|добрый\s+день|"
    r"хай|приветик)\b", re.I)
# «не за что» - это ответ на благодарность, а не начало разговора.
_YOUWELCOME = re.compile(
    r"\b(?:не\s+за\s+что|да\s+не\s+за\s+что|пожалуйста)\b", re.I)

# Вежливость в начале фразы: «спасибо, а...», «извини, но...».
_POLITE = re.compile(
    r"^\s*(?:спасибо|благодарю|спс|извини|извините|прости|простите|"
    r"виноват|виновата|пожалуйста)\b[\s,.:;-]*"
    r"(?:а|но|и|кстати|ещё\s+раз|еще\s+раз)?\s*", re.I)


def strip_politeness(phrase):
    """Убрать вежливость в начале. None - вежливости не было.

    «Спасибо, а что сейчас погода» -> «что сейчас погода». Вопрос идёт дальше
    обычным путём, и колонка отвечает на него, а не рассуждает о вежливости.
    """
    if not phrase:
        return None
    m = _POLITE.match(str(phrase).strip())
    if not m:
        return None
    rest = str(phrase).strip()[m.end():].strip(" ,.:;-—")
    # Короткий остаток - это, скорее всего, просто вежливость целиком.
    if not rest or len(rest) < 3:
        return None
    return rest


def answer(phrase, hour=None):
    """Ответ на вежливость или прощание. None - это не оно."""
    if not phrase:
        return None
    p = " ".join(str(phrase).lower().replace("ё", "е").split())
    if not p:
        return None

    if _BYE.search(p):
        if hour is None:
            import time
            hour = time.localtime().tm_hour
        if _BYE.search(p) and ("ноч" in p or "спокойной" in p):
            if hour < 5 or hour >= 22:
                return "Спокойной ночи.", "bye"
            return "Хорошего вечера.", "bye"
        if "утр" in p:
            return "С добрым утром.", "bye"
        if hour < 5 or hour >= 22:
            return "Спокойной ночи.", "bye"
        if hour < 12:
            return "До встречи.", "bye"
        return "До свидания.", "bye"

    if _THANKS.search(p):
        return "Пожалуйста.", "bye"

    if _SORRY.search(p):
        return "Ничего страшного.", "bye"

    if _YOUWELCOME.search(p):
        return "Пожалуйста.", "bye"

    return None


# ---------------------------------------------------------------------------
# Проверки
# ---------------------------------------------------------------------------
def selfcheck():
    fails = []

    def want(cond, msg):
        if not cond:
            fails.append(msg)

    # Прощания зависят от времени суток, а не от настроения.
    want(answer("спокойной ночи", hour=23) == ("Спокойной ночи.", "bye"),
         "ночью: %r" % (answer("спокойной ночи", hour=23),))
    want(answer("спокойной ночи", hour=14) == ("Хорошего вечера.", "bye"),
         "днём спокойной ночи: %r" % (answer("спокойной ночи", hour=14),))
    want(answer("до свидания", hour=15) == ("До свидания.", "bye"),
         "до свидания: %r" % (answer("до свидания", hour=15),))
    want(answer("пока", hour=10) == ("До встречи.", "bye"),
         "пока утром: %r" % (answer("пока", hour=10),))
    want(answer("доброе утро", hour=8) == ("С добрым утром.", "bye"),
         "доброе утро: %r" % (answer("доброе утро", hour=8),))

    # Благодарность и извинение - коротко, без абзаца.
    for q in ("спасибо", "благодарю", "спс"):
        got = answer(q, hour=14)
        want(got and got[0] == "Пожалуйста.", "%s -> %r" % (q, got))
    want(answer("извини", hour=14) == ("Ничего страшного.", "bye"),
         "извини: %r" % (answer("извини", hour=14),))
    want(answer("не за что", hour=14) == ("Пожалуйста.", "bye"),
         "не за что: %r" % (answer("не за что", hour=14),))

    # Никаких английских вставок и полуслов: именно этим модель отвечала
    # на «спокойной ночи».
    for q in ("спокойной ночи", "до свидания", "пока", "спасибо",
              "извини", "не за что"):
        got = answer(q, hour=14)
        if got:
            txt = got[0]
            want(not re.search(r"[A-Za-z]", txt),
                 "в ответе английские буквы: %r" % txt)
            want(len(txt) <= 40, "ответ слишком длинный: %r" % txt)

    # Вежливость снимается, вопрос остаётся.
    want(strip_politeness("спасибо, а что сейчас погода")
         == "что сейчас погода",
         "снятие вежливости: %r" % strip_politeness("спасибо, а что сейчас погода"))
    want(strip_politeness("извини, но что сейчас время") == "что сейчас время",
         "снятие вежливости с «извини»: %r"
         % strip_politeness("извини, но что сейчас время"))

    # Короткая фраза целиком из вежливости - это не вопрос.
    want(strip_politeness("спасибо") is None, "«спасибо» не вопрос")
    want(strip_politeness("спасибо, а") is None, "«спасибо, а» не вопрос")

    # Обычный вопрос не трогаем.
    for q in ("что сейчас погода", "какая погода в Гомеле", "буди меня в 7 утра",
              "включи свет"):
        want(strip_politeness(q) is None, "вежливость выдумана: %s" % q)

    # Про вопрос без вежливости модуль молчит, а не отвечает наугад.
    want(answer("что сейчас погода", hour=14) is None,
         "на погоду прощаться нельзя")

    for f in fails:
        print("FAIL  " + f)
    if not fails:
        print("ok    jane_bye: вежливость коротко, вопрос после неё остаётся")
    print("ИТОГ: провалено %d" % len(fails))
    return 1 if fails else 0


if __name__ == "__main__":
    import sys
    sys.exit(selfcheck())